/// Native export wrappers for input bindings.
#[unsafe(export_name = "destack.input.device.close")]
pub unsafe extern "C" fn destack_input_device_close(
    handle: resource::InputDeviceHandle,
) -> RuntimeStatus {
    native_call(|context| {
        let _ = &handle;

        context.check_policy(INPUT_DEVICE_CLOSE)?;
        let world = context.check_and_resolve_world(INPUT_DEVICE_CLOSE)?;
        destack_input_device_close_replay(context, world, handle)
    })
}

#[unsafe(export_name = "destack.input.device.list")]
